class Solution {
    public double angleClock(int hour,int minutes){
        double minuteAngle=minutes*6.0,hourAngle=(hour%12)*30.0+minutes*0.5,difference=Math.abs(hourAngle-minuteAngle);
        return Math.min(difference,360.0-difference);
    }
}

code.kotlin:
class Solution {
    fun angleClock(hour:Int,minutes:Int):Double{
        val minuteAngle=minutes*6.0;
        val hourAngle=(hour%12)*30.0+minutes*0.5;
        val difference=kotlin.math.abs(hourAngle-minuteAngle);
        return minOf(difference,360.0-difference)
    }
}

